#ifndef CUDA_RESULTS_CUH
#define CUDA_RESULTS_CUH

#ifdef __cplusplus
extern "C" {
#endif

typedef struct GPU_results_t GPU_results_t;
typedef struct cuda_info_t cuda_info_t;

/// @brief Initialize the structure for storing the results of the partial batch generated by each GPU
/// @param nDevices Number of devices
/// @param n Number of neurons
/// @param s Time steps to simulate
/// @param cuda_info Structure with information about how to perform the simulation in the GPU
/// @return Structure for storing results on each GPU
GPU_results_t** initialize_results_str_in_GPU(size_t nDevices, size_t n, cuda_info_t *cuda_info);

GPU_results_t** initialize_results_str_in_CPU(size_t nDevices, size_t n, cuda_info_t *cuda_info);


/// @brief Copy results structure from the GPU(s) to the CPU
/// @param cpu_results Results structure stored in the CPU
/// @param gpu_results Results structure stored in the GPU
/// @param cuda_info Structure with information about how to perform the simulation in the GPU
/// @param N Number of neurons
/// @param T Time steps simulated
/// @return Structure with the results stored on each GPU
void cpy_batch_results_GPU2CPU(GPU_results_t *cpu_results, GPU_results_t **gpu_results, cuda_info_t *cuda_info, size_t N, size_t T);


#ifdef __cplusplus
}
#endif

#endif